ac:
set -u
cd apps/web
w=src/features/strategy/components/new/new-strategy-wizard.tsx
[ -f "$w" ] || { echo "양성 대조 실패: 위저드 파일이 없다"; exit 1; }
grep -q "indicatorCode=" "$w" || { echo "위저드가 ParseResultPanel 에 indicatorCode 를 안 넘긴다"; exit 1; }
grep -q "onConverted=" "$w" || { echo "위저드가 ParseResultPanel 에 onConverted 를 안 넘긴다"; exit 1; }
grep -q "applyPineSource" "$w" || { echo "위저드가 applyPineSource 를 안 쓴다 — 변환 결과가 에디터로 안 들어간다"; exit 1; }
